display.text:
/* GENERAL DESIGN */

:root {
    --ivory: #F8F4EC;
    --cream: #F5EBDD;
    --beige: #E8DDC9;
    --sand: #D4C4AA;
    --champagne: #C9B99F;
    --brown: #765447;
    --deep-brown: #5C4B3B;
    --text: #514438;
    --white: #FFFDFA;
}

* {
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
    scroll-padding-top: 100px;
}

body {
    margin: 0;
    font-family: Arial, Helvetica, sans-serif;
    background: var(--cream);
    color: var(--text);
    line-height: 1.65;
}

/* HEADER */

header {
    text-align: center;
    padding: 48px 20px 30px;
    background: var(--cream);
    border-bottom: 0;
}

header h1 {
    margin: 0;
    color: var(--deep-brown);
    font-size: clamp(27px, 5vw, 48px);
    line-height: 1.15;
}

.subtitle {
    margin-top: 12px;
    color: var(--brown);
    font-size: 17px;
}

/* SIDE NAVIGATION */

nav {
    position: fixed;
    inset: 0 auto 0 0;
    z-index: 100;
    width: 250px;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 5px;
    padding: 34px 18px;
    overflow-y: auto;
    background: var(--cream);
    border-right: 1px solid var(--sand);
    box-shadow: 3px 0 12px rgba(92, 75, 59, 0.06);
    transform: translateX(-100%);
    transition: transform 240ms ease;
}

nav:hover,
nav:focus-within {
    transform: translateX(0);
}

nav::after {
    content: "Menu";
    position: absolute;
    top: 0;
    left: 100%;
    min-width: 76px;
    padding: 9px 13px;
    color: var(--deep-brown);
    background: var(--cream);
    border: 1px solid var(--sand);
    border-left: 0;
    border-radius: 0 0 7px 0;
    box-shadow: 3px 3px 10px rgba(92, 75, 59, 0.08);
    font-size: 14px;
    font-weight: 600;
    text-align: center;
}

.nav-title {
    margin: 0 8px 18px;
    color: var(--deep-brown);
    font-size: 19px;
}

nav a {
    display: block;
    padding: 10px 12px;
    border-radius: 6px;
    color: var(--deep-brown);
    text-decoration: none;
    font-size: 15px;
    transition: color 180ms ease, background-color 180ms ease, transform 180ms ease;
}

nav a:hover,
nav a:focus-visible {
    color: var(--brown);
    background: var(--beige);
    text-decoration: none;
    transform: translateX(4px);
}

nav a:hover {
    transform: translateX(4px);
}

/* MAIN CONTENT */

header, main, footer {
    margin-left: 250px;
}

main {
    width: min(100% - 36px, 1000px);
    margin-right: auto;
    margin-left: auto;
    transform: translateX(125px);
}

section {
    padding: 58px 0;
    border-bottom: 1px solid var(--beige);
    scroll-margin-top: 85px;
}

section h2 {
    margin: 0 0 18px;
    color: var(--brown);
    font-size: 30px;
    font-weight: 600;
}

section h3 {
    color: var(--deep-brown);
    margin-top: 20px;
}

p {
    margin: 0 0 16px;
}

/* HOME INTRODUCTION */

.intro {
    max-width: 760px;
    margin: 0 auto;
    text-align: center;
    padding: 72px 0 60px;
}

.intro h2 {
    font-size: 32px;
}

/* MEMORY CARDS */

.memory-card {
    background: rgba(255, 253, 250, 0.78);
    border: 1px solid var(--beige);
    border-radius: 10px;
    padding: 22px;
    margin: 18px 0;
}

.section-note {
    color: #796B5D;
    font-style: italic;
}

/* PHOTO PLACEHOLDERS */

.photo-placeholder {
    min-height: 150px;
    display: grid;
    place-items: center;
    padding: 20px;
    text-align: center;
    color: #806E5C;
    background: var(--cream);
    border: 1px dashed var(--champagne);
    border-radius: 8px;
    margin: 18px 0;
}

.photo-grid {
    display: grid;
    grid-template-columns: repeat(
        auto-fit,
        minmax(190px, 1fr)
    );
    gap: 16px;
}

.photo-grid .photo-placeholder {
    min-height: 190px;
    margin: 0;
}

/* FOOTER */

footer {
    padding: 30px 18px;
    text-align: center;
    color: var(--deep-brown);
    background: var(--cream);
}

/* MOBILE DESIGN */

@media (max-width: 600px) {

    header {
        padding-top: 35px;
    }

    nav {
        position: relative;
        width: 100%;
        flex-direction: row;
        justify-content: center;
        gap: 4px;
        padding: 12px;
        border-right: 0;
        border-bottom: 1px solid var(--sand);
        transform: none;
        transition: none;
    }

    nav::after {
        content: none;
    }

    .nav-title {
        width: 100%;
        margin: 0 0 4px;
        text-align: center;
    }

    nav a {
        padding: 7px 9px;
        font-size: 14px;
    }

    header, main, footer {
        margin-left: 0;
    }

    main {
        transform: none;
    }

    section {
        padding: 42px 0;
    }

    section h2 {
        font-size: 26px;
    }
}

