async function fetchPhotos({pageSize=50, pageToken}={}) {
  const s = readSession(); if(!s) return {items:[]};
  const r = await fetch('https://photoslibrary.googleapis.com/v1/mediaItems:search', {
    method:'POST',
    headers:{Authorization:`Bearer ${s.token}`,'Content-Type':'application/json'},
    body: JSON.stringify({pageSize, pageToken})
  });
  if (!r.ok) { if (r.status===401) { sessionStorage.removeItem(TOKEN_KEY); } throw new Error('photos '+r.status); }
  const data = await r.json();
  return {items: (data.mediaItems||[]).filter(m=>m.mediaMetadata?.photo), nextPageToken: data.nextPageToken};
}
```

