const HOME_PAGE = "index.html";

const isLoginPage = () => location.pathname.endsWith(LOGIN_PAGE);

function readSession() {
  try {
    const raw = sessionStorage.getItem(TOKEN_KEY);
    if (!raw) return null;
    const data = JSON.parse(raw);
    if (!data.token || !data.exp || Date.now() >= data.exp) return null;
    return data;
  } catch (error) {
    return null;
  }
}

function readUser() {
  try { return JSON.parse(localStorage.getItem(USER_KEY) || "null"); }
  catch (error) { return null; }
}

function saveSession(token, expiresIn, user) {
  const lifetime = Math.max(60, (Number(expiresIn) || 3600) - 60);
  sessionStorage.setItem(TOKEN_KEY, JSON.stringify({ token, exp: Date.now() + lifetime * 1000 }));
  if (user) localStorage.setItem(USER_KEY, JSON.stringify(user));
}

function clearSession() {
  sessionStorage.removeItem(TOKEN_KEY);
  localStorage.removeItem(USER_KEY);
}

function isConfigured() {
  return /\.apps\.googleusercontent\.com$/.test(GOOGLE_CLIENT_ID) && !GOOGLE_CLIENT_ID.startsWith("PON_");
}
