const GOOGLE_CLIENT_ID = "PON_TU_CLIENT_ID.apps.googleusercontent.com";
const PHOTOS_SCOPE = "https://www.googleapis.com/auth/photoslibrary.readonly";
const AUTH_SCOPE = "openid email profile " + PHOTOS_SCOPE;
const TOKEN_KEY = "simon_token";
const USER_KEY = "simon_user";
const LOGIN_PAGE = "login.html";
const HOME_PAGE = "index.html";

function isLoginPage() {
  return location.pathname.endsWith(LOGIN_PAGE);
}

function isConfigured() {
  return (
    /\.apps\.googleusercontent\.com$/.test(GOOGLE_CLIENT_ID) &&
    !GOOGLE_CLIENT_ID.startsWith("PON_")
  );
}

function readSession() {
  try {
    const raw = sessionStorage.getItem(TOKEN_KEY);
    if (!raw) return null;
    const data = JSON.parse(raw);
    if (!data.token || !data.exp || Date.now() >= data.exp) return null;
    return data;
  } catch (error) {
    return null;
  }
}

function isLoggedIn() {
  return Boolean(readSession());
}

function readUser() {
  try {
    return JSON.parse(localStorage.getItem(USER_KEY) || "null");
  } catch (error) {
    return null;
  }
}

function saveSession(token, expiresIn, user) {
  const lifetime = Math.max(60, (Number(expiresIn) || 3600) - 60);
  sessionStorage.setItem(
    TOKEN_KEY,
    JSON.stringify({ token, exp: Date.now() + lifetime * 1000 })
  );
  if (user) {
    localStorage.setItem(USER_KEY, JSON.stringify(user));
  }
}

function clearSession() {
  sessionStorage.removeItem(TOKEN_KEY);
  localStorage.removeItem(USER_KEY);
}

let gisPromise = null;

function loadGis() {
  if (window.google && window.google.accounts && window.google.accounts.oauth2) {
    return Promise.resolve();
  }
  if (gisPromise) return gisPromise;
  gisPromise = new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = "https://accounts.google.com/gsi/client";
    script.async = true;
    script.defer = true;
    script.onload = () => resolve();
    script.onerror = () =>
      reject(new Error("No se pudo cargar Google Identity Services."));
    document.head.appendChild(script);
  });
  return gisPromise;
}

async function fetchUserInfo(token) {
  const response = await fetch("https://www.googleapis.com/oauth2/v3/userinfo", {
    headers: { Authorization: "Bearer " + token },
  });
  if (!response.ok) {
    throw new Error("No se pudo obtener el perfil de Google.");
  }
  return response.json();
}

async function signIn() {
  if (!isConfigured()) {
    throw new Error(
      "Falta configurar el Client ID de Google en auth.js."
    );
  }
  await loadGis();
  return new Promise((resolve, reject) => {
    const client = google.accounts.oauth2.initTokenClient({
      client_id: GOOGLE_CLIENT_ID,
      scope: AUTH_SCOPE,
      callback: async (response) => {
        if (response.error) {
          reject(new Error(response.error));
          return;
        }
        try {
          const user = await fetchUserInfo(response.access_token);
          saveSession(response.access_token, response.expires_in, user);
          resolve(user);
        } catch (error) {
          reject(error);
        }
      },
      error_callback: (error) =>
        reject(new Error((error && error.type) || "google_auth_error")),
    });
    client.requestAccessToken({ prompt: "" });
  });
}

function signOut() {
  const session = readSession();
  if (session && window.google && window.google.accounts && window.google.accounts.oauth2) {
    try {
      google.accounts.oauth2.revoke(session.token, () => {});
    } catch (error) {}
  }
  clearSession();
  location.replace(LOGIN_PAGE);
}

function photoUrl(item, width = 1000, height = 1000) {
  return item && item.baseUrl ? item.baseUrl + "=w" + width + "-h" + height : "";
}

async function fetchPhotos(options) {
  const settings = options || {};
  const session = readSession();
  if (!session) return { items: [], nextPageToken: null };
  const body = { pageSize: Math.min(Number(settings.pageSize) || 50, 100) };
  if (settings.pageToken) body.pageToken = settings.pageToken;
  const response = await fetch(
    "https://photoslibrary.googleapis.com/v1/mediaItems:search",
    {
      method: "POST",
      headers: {
        Authorization: "Bearer " + session.token,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    }
  );
  if (response.status === 401) {
    clearSession();
    location.replace(LOGIN_PAGE);
    return { items: [], nextPageToken: null };
  }
  if (!response.ok) {
    throw new Error("Google Photos respondió " + response.status + ".");
  }
  const data = await response.json();
  const items = (data.mediaItems || []).filter(
    (item) => item.mediaMetadata && item.mediaMetadata.photo
  );
  return { items, nextPageToken: data.nextPageToken || null };
}

function renderPhotoCard(item, width, height) {
  const image = document.createElement("img");
  image.src = photoUrl(item, width, height);
  image.alt = item.description || item.filename || "Foto de Google Photos";
  image.loading = "lazy";
  image.referrerPolicy = "no-referrer";
  return image;
}

function mountUserChip() {
  if (isLoginPage()) return;
  const header = document.querySelector("header");
  if (!header || document.querySelector(".user-chip")) return;
  const user = readUser();
  const chip = document.createElement("div");
  chip.className = "user-chip";
  if (user) {
    if (user.picture) {
      const avatar = document.createElement("img");
      avatar.src = user.picture;
      avatar.alt = user.name || "Usuario";
      avatar.referrerPolicy = "no-referrer";
      chip.appendChild(avatar);
    }
    const name = document.createElement("span");
    name.className = "user-name";
    name.textContent = user.name || user.email || "Sesión de Google";
    chip.appendChild(name);
    const button = document.createElement("button");
    button.type = "button";
    button.className = "sign-out";
    button.textContent = "Salir";
    button.addEventListener("click", signOut);
    chip.appendChild(button);
  } else {
    const link = document.createElement("a");
    link.href = LOGIN_PAGE;
    link.textContent = "Iniciar sesión";
    chip.appendChild(link);
  }
  header.appendChild(chip);
}

function ensurePhotoSection() {
  if (isLoginPage()) return null;
  const existing = document.querySelector("#google-photos-grid");
  if (existing) return existing;
  if (document.querySelector(".photo-placeholder")) return null;
  const main = document.querySelector("main");
  if (!main) return null;
  const section = document.createElement("section");
  section.className = "photo-sync";
  const title = document.createElement("h2");
  title.textContent = "Google Photos";
  const text = document.createElement("p");
  text.textContent = "Fotos sincronizadas desde tu cuenta de Google.";
  const grid = document.createElement("div");
  grid.className = "photo-grid";
  grid.id = "google-photos-grid";
  section.appendChild(title);
  section.appendChild(text);
  section.appendChild(grid);
  main.appendChild(section);
  return grid;
}

function fillPhotoGrid(grid, items) {
  grid.textContent = "";
  if (!items.length) {
    const message = document.createElement("p");
    message.className = "photos-error";
    message.textContent = "No encontramos fotos en tu cuenta de Google.";
    grid.appendChild(message);
    return;
  }
  items.slice(0, 12).forEach((item) => {
    const card = document.createElement("figure");
    card.className = "photo-card";
    card.appendChild(renderPhotoCard(item, 800, 800));
    const caption = document.createElement("figcaption");
    caption.textContent = item.filename || "";
    card.appendChild(caption);
    grid.appendChild(card);
  });
}

function fillPlaceholders(items) {
  const slots = Array.from(document.querySelectorAll(".photo-placeholder"));
  if (!slots.length || !items.length) return;
  slots.forEach((slot, index) => {
    const item = items[index % items.length];
    slot.classList.add("has-photo");
    slot.textContent = "";
    slot.appendChild(renderPhotoCard(item, 900, 700));
  });
}

async function loadPhotos() {
  if (isLoginPage() || !isLoggedIn()) return;
  const grid = ensurePhotoSection();
  const placeholders = document.querySelectorAll(".photo-placeholder");
  if (!grid && !placeholders.length) return;
  try {
    const result = await fetchPhotos({ pageSize: 50 });
    if (grid) fillPhotoGrid(grid, result.items);
    fillPlaceholders(result.items);
  } catch (error) {
    if (grid) {
      grid.textContent = "";
      const message = document.createElement("p");
      message.className = "photos-error";
      message.textContent =
        "No se pudieron cargar las fotos: " + (error.message || "error desconocido");
      grid.appendChild(message);
    }
    console.error("Google Photos:", error);
  }
}

function wireSyncButton() {
  const button = document.querySelector("#sync-photos");
  if (!button) return;
  button.addEventListener("click", async () => {
    button.disabled = true;
    button.textContent = "Sincronizando...";
    await loadPhotos();
    button.disabled = false;
    button.textContent = "Sincronizar con Google Photos";
  });
}

function init() {
  mountUserChip();
  wireSyncButton();
  loadPhotos();
}

if (!isLoginPage() && !isLoggedIn()) {
  location.replace(LOGIN_PAGE);
}

document.addEventListener("DOMContentLoaded", init);

window.SimonAuth = {
  signIn,
  signOut,
  isConfigured,
  isLoggedIn,
  readUser,
  fetchPhotos,
  loadPhotos,
  photoUrl,
  HOME_PAGE,
};

