async function listPickedItems(sessionId) {
  const session = readSession();
  const items = [];
  let pageToken = "";
  for (let page = 0; page < 5; page++) {
    const params = new URLSearchParams({ sessionId, pageSize: "100" });
    if (pageToken) params.set("pageToken", pageToken);
    const res = await fetch("https://photospicker.googleapis.com/v1/mediaItems?" + params.toString(), {
      headers: { Authorization: "Bearer " + session.token },
    });
    if (!res.ok) throw new Error("No se pudieron leer las fotos seleccionadas (" + res.status + ").");
    const data = await res.json();
    (data.mediaItems || []).forEach((item) => {
      if (item.type !== "PHOTO" || !item.mediaFile || !item.mediaFile.baseUrl) return;
      items.push({ id: item.id, baseUrl: item.mediaFile.baseUrl, filename: item.mediaFile.filename || "" });
